<script>
(function(){
  var exp=document.getElementById('efExp'),months=document.getElementById('efMonths'),
      have=document.getElementById('efHave'),monthly=document.getElementById('efMonthly'),
      targetEl=document.getElementById('efTarget'),detEl=document.getElementById('efDetail'),fillEl=document.getElementById('efFill');
  function money(n){return '$'+Math.round(n).toLocaleString('en-US');}
  function dur(m){var y=Math.floor(m/12),mo=m%12;var s=[];if(y)s.push(y+(y===1?' year':' years'));if(mo)s.push(mo+(mo===1?' month':' months'));return s.join(' ')||'0 months';}
  function calc(){
    var e=parseFloat(exp.value)||0, mo=parseInt(months.value,10)||3,
        h=parseFloat(have.value)||0, m=parseFloat(monthly.value)||0;
